    top,bot=min(rs),max(rs); left,right=min(cs),max(cs)
    marker=next((i,j) for i in range(top+1,bot) for j in range(left+1,right) if g[i][j]==3)
    mi,mj=marker
    for i in range(top+1,bot):
        for j in range(left+1,right):
